pm.test('deep', () => pm.expect({a: [1, 2]}).to.deep.equal({a: [1, 2]}));
pm.test('include', () => pm.expect([1, 2, 3]).to.include(2));
pm.test('property', () => pm.expect({a: {b: 1}}).to.have.nested.property('a.b', 1));
pm.test('type', () => pm.expect('x').to.be.a('string'));
pm.test('length', () => pm.expect([1]).to.have.lengthOf(2));
pm.test('oneOf', () => pm.expect(3).to.be.oneOf([1, 2]));
pm.test('match', () => pm.expect('abc').to.match(/^a/));
pm.test('keys', () => pm.expect({a: 1, b: 2}).to.have.all.keys('a', 'b'));
pm.test('above', () => pm.expect(5).to.be.above(10));
pm.test('not', () => pm.expect(null).to.not.be.ok);
pm.test('closeTo', () => pm.expect(1.5).to.be.closeTo(1, 0.1));
pm.test('members', () => pm.expect([1, 2]).to.have.members([2, 1]));
pm.test('throw', () => pm.expect(() => { throw new TypeError('x') }).to.throw(TypeError));
